import{_ as a,a as s,b as i}from"./chunks/workbench.CkAH1RwQ.js";import{_ as t,o,c as p,a2 as r}from"./chunks/framework.Ky-Ipuyb.js";const b=JSON.parse('{"title":"ImGui 示例","description":"","frontmatter":{"lang":"zh-CN","sourcePath":"packages/sfml.js-imgui/examples/README.zh-CN.md"},"headers":[],"relativePath":"zh/examples/imgui.md","filePath":"zh/examples/imgui.md"}'),m={name:"zh/examples/imgui.md"};function n(l,e,c,d,h,g){return o(),p("div",null,[...e[0]||(e[0]=[r('<h1 id="imgui-示例" tabindex="-1">ImGui 示例 <a class="header-anchor" href="#imgui-示例" aria-label="Permalink to &quot;ImGui 示例&quot;">​</a></h1><p>在原生 SFML 窗口中运行 Dear ImGui 控件。先体验控件演示，再通过场景面板和综合工作台，了解控件状态如何驱动 SFML 图形。</p><h2 id="运行准备" tabindex="-1">运行准备 <a class="header-anchor" href="#运行准备" aria-label="Permalink to &quot;运行准备&quot;">​</a></h2><p>以下命令均在 <strong>monorepo 根目录</strong>执行。首次运行 bootstrap 安装依赖并构建各包。需要显示环境和 OpenGL，详见<a href="/zh/guide/getting-started#requirements">平台要求</a>。</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">node</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> tools/bootstrap.cjs</span></span></code></pre></div><p>修改 ImGui TypeScript 源码后，执行 <code>npm run build:ts --prefix packages/sfml.js-imgui</code>。示例使用本地构建的包。</p><h2 id="示例" tabindex="-1">示例 <a class="header-anchor" href="#示例" aria-label="Permalink to &quot;示例&quot;">​</a></h2><div class="example-gallery"><article class="example-entry" id="demo"><a href="/media/imgui/examples/screenshots/demo.png"><img src="'+a+'" width="360" alt="已展开 Tables and Columns 的 Dear ImGui 演示窗口"></a><div class="example-info"><p><strong><a href="https://github.com/XadillaX/node-sfml/blob/main/packages/sfml.js-imgui/examples/demo.cjs">demo.cjs</a></strong></p><p>Dear ImGui 控件演示</p><p><code>node packages/sfml.js-imgui/examples/demo.cjs</code></p><p><strong>操作</strong>：展开内置演示窗口中的控件、布局、表格和曲线。 独立的 sfml.js-imgui 面板显示帧计数和 Reset 按钮。关闭窗口退出。 </p></div></article></div><article class="example-entry" id="scene-inspector"><a href="/media/imgui/examples/screenshots/scene-inspector.png"><img src="'+s+'" width="360" alt="场景面板中的 SFML 圆形和 ImGui 颜色选择器"></a><div class="example-info"><p><strong><a href="https://github.com/XadillaX/node-sfml/blob/main/packages/sfml.js-imgui/examples/scene-inspector.cjs">scene-inspector.cjs</a></strong></p><p>用 ImGui 面板控制运动中的 SFML 圆形</p><p><code>node packages/sfml.js-imgui/examples/scene-inspector.cjs</code></p><p><strong>操作</strong>：用 Animate、Speed、Radius 和 Color 修改场景， Reset scene 恢复默认值。点击面板外再按空格，可在不影响活动控件的情况下暂停或恢复。 </p><p><a href="/zh/imgui/widgets">控件与状态</a></p></div></article><article class="example-entry" id="workbench"><a href="/media/imgui/examples/screenshots/workbench.png"><img src="'+i+'" width="360" alt="包含文本输入、选择列表、表格和曲线的 ImGui 综合工作台"></a><div class="example-info"><p><strong><a href="https://github.com/XadillaX/node-sfml/blob/main/packages/sfml.js-imgui/examples/workbench.cjs">workbench.cjs</a></strong></p><p>文本输入、回调、表格、弹窗与自定义绘制</p><p><code>node packages/sfml.js-imgui/examples/workbench.cjs</code></p><p><strong>操作</strong>：编辑 Name，选择对象，切换表格行，并通过 Scene → Reset… 打开确认弹窗。可在命令后追加 TTF 路径加载自定义拉丁字体。 </p><p><a href="/zh/imgui/layout">布局</a> · <a href="/zh/imgui/callbacks">回调</a> · <a href="/zh/imgui/rendering">渲染</a></p></div></article><p>三个示例都会转发全部事件；即使窗口折叠，<code>Begin</code> 与 <code>End</code> 也始终配对；类型化数组状态保留在帧循环外；退出时先关闭 ImGui，再关闭 SFML 窗口。截图均来自 macOS 上实际运行的原生示例。</p><p><a href="/zh/examples">全部示例</a> · <a href="/zh/imgui/getting-started">ImGui 快速开始</a></p>',12)])])}const x=t(m,[["render",n]]);export{b as __pageData,x as default};
